-- P1 correo: referencias del catalogo simulado y reglas comerciales; sin usuarios ni ventas.
-- Ejecutar despues de esquema.sql, con ON_ERROR_STOP y --single-transaction.
SET search_path TO public;
SELECT setval(pg_get_serial_sequence('public.catalogo_cache','id'), COALESCE((SELECT max(id) FROM public.catalogo_cache),1), EXISTS(SELECT 1 FROM public.catalogo_cache));
SELECT setval(pg_get_serial_sequence('public.motivos_perdida','id'), COALESCE((SELECT max(id) FROM public.motivos_perdida),1), EXISTS(SELECT 1 FROM public.motivos_perdida));
SELECT setval(pg_get_serial_sequence('public.descuentos','id'), COALESCE((SELECT max(id) FROM public.descuentos),1), EXISTS(SELECT 1 FROM public.descuentos));
